     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	
     9	/**
    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    11	 * high-season nights; the rate plan then decides whether it accepts the stay and what it costs (a
    12	 * discount on the sum, or its own price). Money is rounded to cents (half-even) at every step.
    13	 */
    14	public final class PriceCalculator {
    15	
    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    17	
    18	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    19	        return calculate(room, checkIn, checkOut, ratePlan, null);
    20	    }
    21	
    22	    public Price calculate(
    23	            Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
    24	        int nights = 0;
    25	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    26	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    27	            subtotal = subtotal.add(nightPrice(room, night));
    28	            nights++;
    29	        }
    30	        Stay stay = new Stay(room, checkIn, checkOut, companyCode, nights, subtotal);
    31	        ratePlan.check(stay);
    32	        return ratePlan.price(stay);
    33	    }
    34	
    35	    BigDecimal nightPrice(Room room, LocalDate night) {
    36	        BigDecimal nightlyRate = room.nightlyRate();
    37	        if (isHighSeason(night)) {
    38	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    39	        }
    40	        return cents(nightlyRate);
    41	    }
    42	
    43	    /** High season: from December 15 to the end of February, and the whole of July. */
    44	    static boolean isHighSeason(LocalDate date) {
    45	        Month month = date.getMonth();
    46	        return month == Month.JANUARY
    47	                || month == Month.FEBRUARY
    48	                || month == Month.JULY
    49	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    50	    }
    51	
    52	    static BigDecimal cents(BigDecimal value) {
    53	        return value.setScale(2, RoundingMode.HALF_EVEN);
    54	    }
    55	}
    56	package hotel.reservations;
    57	
    58	import hotel.documents.ReservationReceipt;
    59	import hotel.messages.EmailSender;
    60	import hotel.rooms.Room;
    61	import hotel.rooms.Rooms;
    62	
    63	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    64	public final class ReservationService {
    65	
    66	    static final String HOTEL_NAME = "Pousada Maré Alta";
    67	
    68	    private final Rooms rooms;
    69	    private final ReservationStore store;
    70	    private final PriceCalculator priceCalculator;
    71	    private final EmailSender emailSender;
    72	
    73	    public ReservationService(
    74	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    75	        this.rooms = rooms;
    76	        this.store = store;
    77	        this.priceCalculator = priceCalculator;
    78	        this.emailSender = emailSender;
    79	    }
    80	
    81	    public synchronized Reservation create(NewReservation request) {
    82	        if (!request.checkOut().isAfter(request.checkIn())) {
    83	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    84	        }
    85	        if (request.guests() < 1) {
    86	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    87	        }
    88	        Room room = rooms.find(request.roomNumber())
    89	                .orElseThrow(() -> new HotelException(
    90	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    91	        if (request.guests() > room.capacity()) {
    92	            throw new HotelException(
    93	                    ErrorCode.CAPACITY_EXCEEDED,
    94	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    95	        }
    96	        Price price = priceCalculator.calculate(
    97	                room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
    98	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    99	            throw new HotelException(
   100	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
   101	        }
   102	        return store.add(request, price);
   103	    }
   104	
   105	    public Reservation find(long reservationId) {
   106	        return store.find(reservationId)
   107	                .orElseThrow(() -> new HotelException(
   108	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
   109	    }
   110	
   111	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
   112	    public synchronized Reservation confirm(long reservationId) {
   113	        Reservation reservation = find(reservationId);
   114	        if (reservation.status() != ReservationStatus.PENDING) {
   115	            throw notAllowed(reservation, "confirm");
   116	        }
   117	        reservation.confirmPayment();
   118	        store.update(reservation);
   119	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
   120	        emailSender.send(
   121	                reservation.guest().email(),
   122	                "Reserva confirmada - " + HOTEL_NAME,
   123	                confirmationEmailBody(reservation, receipt));
   124	        return reservation;
   125	    }
   126	
   127	    /**
   128	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
   129	     * reservation was never paid, so nothing comes back).
   130	     */
   131	    public synchronized Reservation cancel(long reservationId) {
   132	        Reservation reservation = find(reservationId);
   133	        if (reservation.status() != ReservationStatus.PENDING
   134	                && reservation.status() != ReservationStatus.CONFIRMED) {
   135	            throw notAllowed(reservation, "cancel");
   136	        }
   137	        reservation.cancel(reservation.ratePlan().refund(reservation.amountPaid()));
   138	        store.update(reservation);
   139	        return reservation;
   140	    }
   141	
   142	    public synchronized Reservation checkIn(long reservationId) {
   143	        Reservation reservation = find(reservationId);
   144	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   145	            throw notAllowed(reservation, "check in");
   146	        }
   147	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   148	        store.update(reservation);
   149	        return reservation;
   150	    }
   151	
   152	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   153	    public synchronized ReservationReceipt checkOut(long reservationId) {
   154	        Reservation reservation = find(reservationId);
   155	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   156	            throw notAllowed(reservation, "check out");
   157	        }
   158	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   159	        store.update(reservation);
   160	        return new ReservationReceipt(reservation, roomOf(reservation));
   161	    }
   162	
   163	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   164	    public ReservationReceipt receiptCopy(long reservationId) {
   165	        Reservation reservation = find(reservationId);
   166	        if (!reservation.isPaid()) {
   167	            throw notAllowed(reservation, "issue a receipt for");
   168	        }
   169	        return new ReservationReceipt(reservation, roomOf(reservation));
   170	    }
   171	
   172	    private Room roomOf(Reservation reservation) {
   173	        return rooms.find(reservation.roomNumber()).orElseThrow();
   174	    }
   175	
   176	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   177	        return "Olá, " + reservation.guest().name() + "!\n\n"
   178	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   179	                + receipt.text() + "\n"
   180	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   181	                + "Até breve!\n";
   182	    }
   183	
   184	    private static HotelException notAllowed(Reservation reservation, String operation) {
   185	        return new HotelException(
   186	                ErrorCode.OPERATION_NOT_ALLOWED,
   187	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   188	    }
   189	}

